oindent 	extsf{Remark 2} \emph{As it turns out, only the first components $M_j^L$ and its Hilbert analogue $H_j^L$ are sensitive to the existent distinction between \eqref{nzh} and \eqref{mzh}. Consequently, for the last two components one will be able to identify $M_j^{H
ot\Delta}$ and $M_j^{H\Delta}$ with their analogue $H_j^{H
ot\Delta}$ and $H_j^{H\Delta}$, respectively.}

$
ewline$ As we did for the proof of \eqref{l2c2}, we write \eqref{Tjm-pqr} as  egin{equation} \|T_{j,m}(f,g)\|_r\lesssim_{\gamma}(1+m^{1- rac{1}{r}})2^{- rac{m}{20r}}\|f*\check{\phi}_{m+j}\|_{2r}\|g*\check{\phi}_{\gamma,m,j}\|_{2r}, \end{equation} where here we used that $p=q=2r$ and that $(2r)^*= rac{2r}{2r-1}$ since $r\ge 1$. Since  egin{equation*} |T_{j(x),m}(f,g)(x)|\le \Big(\sum_{j\in\mathbb{Z}}|T_{j,m}(f,g)|^r\Big)^ rac{1}{r}, \end{equation*} it follows from H"older inequality and Proposition ef{Tjmb} that  egin{align}  ig\|T_{j(x),m}(f,g)(x) ig\|_{L^r(dx)}&\le \Big(\sum_{j\in\mathbb{Z}}\|T_{j,m}(f,g)\|_r^r\Big)^ rac{1}{r}
onumber\ &\le (1+m^{1- rac{1}{r}})2^{- rac{m}{20r}} \Big(\sum_{j\in\mathbb{Z}}\|f*\check{\phi}_{m+j}\|_{2r}^r\|g*\check{\phi}_{\gamma,m,j}\|_{2r}^r\Big)^ rac{1}{r}. \end{align} Notice that for $r\in [1,\infty)$ and for any $f, \phi\in\mathcal{S}(\mathbb{R})$, we have  egin{align*} \Big(\sum_{j\in\mathbb{Z}}\|f*\phi_j\|_{2r}^{2r}\Big)^ rac{1}{2r}&\le \Bigg(\int_\mathbb{R} \sum_{j\in\mathbb{Z}}|(f*\phi_j)(x)|^{2r}dx\Bigg)^ rac{1}{2r}\ &\le \Bigg(\int_\mathbb{R} \Bigg(\sum_{j\in\mathbb{Z}}|(f*\phi_j)(x)|^2\Bigg)^rdx\Bigg)^ rac{1}{2r} = \Bigg(\int_\mathbb{R} \Bigg\{ igg(\sum_{j\in\mathbb{Z}}|(f*\phi_j)(x)|^2 igg)^ rac{1}{2}\Bigg\}^{2r}dx\Bigg)^ rac{1}{2r}\ &=\Bigg\| igg(\sum_{j\in\mathbb{Z}}|f*\phi_j(x)|^2 igg)^ rac{1}{2}\Bigg\|_{2r} \lesssim \|f\|_{2r}, \end{align*} here for the last relation we used standard Littlewood-Paley theory. By Cauchy Schwartz, the hypothesis on $\gamma\in \mathcal{NF}$ and the result above, we obtain  egin{align} \Big(\sum_{j\in\mathbb{Z}}\|f*\check{\phi}_{m+j}\|_{2r}^r\|g*\check{\phi}_{\gamma,m,j}\|_{2r}^r\Big)^ rac{1}{r}&\le \Big(\sum_{j\in\mathbb{Z}}\|f*\check{\phi}_{m+j}\|_{2r}^{2r}\Big)^ rac{1}{2r}\Big(\sum_{j\in\mathbb{Z}}\|g*\check{\phi}_{\gamma,m,j}\|_{2r}^{2r}\Big)^ rac{1}{2r} 
onumber\ &\le_{\gamma,r} \|f\|_{2r}\|g\|_{2r}. \end{align} Inserting \eqref{fg2r} in \eqref{supTjm} we get  egin{equation}  ig\|T_{j(x),m}(f,g)(x) ig\|_{L^r(dx)}\le_{\gamma,r} (1+m^{1- rac{1}{r}})2^{- rac{m}{20r}}\|f\|_{2r}\|g\|_{2r}, \end{equation} as desired.
